import React, { useState, useCallback } from 'react';
import { Calendar, ButtonGroup, Button, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
  initialDate?: Date;
}

const startOfDay = (d: Date): Date => {
  const copy = new Date(d);
  copy.setHours(0, 0, 0, 0);
  return copy;
};

const addDays = (d: Date, days: number): Date => {
  const copy = new Date(d);
  copy.setDate(copy.getDate() + days);
  return copy;
};

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const handleSelect = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const isSame = (a: Date, b: Date) => a.getTime() === b.getTime();

  return (
    <Stack direction="column" gap="var(--jx-space-md)" className="jx-report-date-picker">
      <ButtonGroup>
        <Button
          variant={isSame(selectedDate, today) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleSelect(today)}
        >
          Сегодня
        </Button>
        <Button
          variant={isSame(selectedDate, yesterday) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleSelect(yesterday)}
        >
          Вчера
        </Button>
        <Button
          variant={isSame(selectedDate, weekAgo) ? 'primary' : 'secondary'}
          size="sm"
          onClick={() => handleSelect(weekAgo)}
        >
          Неделя назад
        </Button>
      </ButtonGroup>

      <Calendar
        view="month"
        selectedDate={selectedDate}
        onSelectDate={handleSelect}
        className="jx-report-date-picker__calendar"
      />
    </Stack>
  );
};

export default ReportDatePicker;

